var STORAGE_KEY='lcadvance_volumes';function getStoredVolumes(){try{var stored=localStorage.getItem(STORAGE_KEY);if(stored)return JSON.parse(stored);}catch(e){}return{principal:0.1,ambiental:0.8,examenes:0.8};}function saveVolumes(volumes){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(volumes));}catch(e){}}var _vcCss=document.createElement('style');_vcCss.textContent='.vol-btn{background:rgba(0,229,255,0.1);border:1px solid rgba(0,229,255,0.5);border-radius:6px;padding:6px 10px;cursor:pointer;color:#00e5ff;font-size:16px;transition:all .3s ease}.vol-btn:hover{background:rgba(0,229,255,0.2);border-color:#00e5ff}.vol-slider{display:none;background:rgba(0,0,0,0.9);border:1px solid rgba(0,229,255,0.5);border-radius:6px;padding:8px}.vol-slider.show{display:block}.vol-slider input{width:100px;cursor:pointer;-webkit-appearance:none;background:#222;height:12px;border:2px solid #00e5ff;border-radius:4px}.vol-slider input::-webkit-slider-thumb{-webkit-appearance:none;width:16px;height:20px;background:#c9408a;border:2px solid #fff;cursor:pointer;border-radius:4px}.header-volume{display:flex;align-items:center;gap:8px;margin-left:15px}@media(max-width:768px){.vol-btn{padding:4px 6px;font-size:14px}.vol-slider{padding:6px}.vol-slider input{width:80px;height:10px}.vol-slider input::-webkit-slider-thumb{width:14px;height:16px}}';document.head.appendChild(_vcCss);function initVolumeControl(config){var audio=document.getElementById(config.audioId);var slider=document.getElementById(config.sliderId);var btn=document.getElementById(config.btnId);var container=document.getElementById(config.containerId);var volumes=getStoredVolumes();if(!audio||!slider)return volumes;var channel=config.channel||'principal';var vol=volumes[channel]!==undefined ? volumes[channel]:(config.defaultVol||0.1);slider.value=vol;audio.volume=parseFloat(vol);slider.addEventListener('input',function(){var val=parseFloat(this.value);volumes[channel]=val;audio.volume=val;saveVolumes(volumes);if(btn)btn.textContent=val>0 ? '\u{1F50A}':'\u{1F507}';});if(btn&&container){if(!btn.hasAttribute('aria-label'))btn.setAttribute('aria-label','Ajustar volumen');btn.addEventListener('click',function(e){e.stopPropagation();var d=container.style.display;container.style.display=(d==='flex'||d==='block')? 'none':'flex';});document.addEventListener('click',function(){container.style.display='none';});container.addEventListener('click',function(e){e.stopPropagation();});}if(config.autoplay!==false){audio.play()['catch'](function(){});}return volumes;}